-- SQL script to create the required DB and schema for BSTORE in PostgreSQL

-- 1. Create database (execute connected as superuser, e.g. postgres)
-- In PostgreSQL psql:
-- CREATE DATABASE bstore WITH ENCODING 'UTF8';

-- Optionally create a DB user with restricted permissions
-- CREATE USER bstore_user WITH PASSWORD 'your_secure_password';
-- GRANT ALL PRIVILEGES ON DATABASE bstore TO bstore_user;

-- 2. Connect to the database:
-- \c bstore

-- 3. Schema DDL for products table (converted from MySQL/H2 syntax)
-- AUTO_INCREMENT is converted to BIGSERIAL / GENERATED BY DEFAULT AS IDENTITY
-- TINYINT(1) is converted to BOOLEAN
CREATE TABLE IF NOT EXISTS products (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(255),
    category VARCHAR(255),
    price DOUBLE PRECISION,
    image VARCHAR(1000),
    badge VARCHAR(255),
    sold_out BOOLEAN NOT NULL DEFAULT FALSE
);

-- 4. Initial seed data (optional / sample)
-- INSERT INTO products (name, category, price, image, badge, sold_out)
-- VALUES ('Sample Product', 'Electronics', 99.99, 'https://example.com/item.png', 'New', false);

